const items = $input.all();
const rows = [];
let row = [];
for (const it of items) {
  const c = it.json;
  row.push({ text: c.name, callback_data: `d_${c.id}_0` });
  if (row.length === 2) { rows.push(row); row = []; }
}
if (row.length) rows.push(row);
rows.push([{ text: "🏠 Главное меню", callback_data: "back_to_menu" }]);

const cb = $('Telegram Trigger').first().json.callback_query;
return [{
  json: {
    chat_id: cb.message.chat.id,
    text: "🌍 Выберите город:",
    reply_markup: { inline_keyboard: rows }
  }
}];

const PAGE = 8;
const cb = $('Telegram Trigger').first().json.callback_query;
const parts = cb.data.split('_');
const cityId = parts[1];
const page = parseInt(parts[2]) || 0;

const items = $input.all().map(i => i.json).filter(r => r.id);
const hasNext = items.length > PAGE;
const list = hasNext ? items.slice(0, PAGE) : items;
const cityName = list.length ? list[0].city_name : null;

const rows = [];
rows.push([{
  text: cityName ? `📍 Весь город ${cityName}` : "📍 Выбрать этот город",
  callback_data: `s_${cityId}`
}]);

let row = [];
for (const d of list) {
  row.push({ text: `${d.name}`, callback_data: `s_${d.id}` });
  if (row.length === 2) { rows.push(row); row = []; }
}
if (row.length) rows.push(row);

const nav = [];
if (page > 0) nav.push({ text: "⬅️ Назад", callback_data: `d_${cityId}_${page - 1}` });
if (hasNext) nav.push({ text: "Дальше ➡️", callback_data: `d_${cityId}_${page + 1}` });
if (nav.length) rows.push(nav);
rows.push([{ text: "⬅️ К городам", callback_data: "add_city" }]);

const text = cityName
  ? `📍 ${cityName}: выберите район или весь город`
  : "📍 Для этого города районов нет. Можно выбрать его целиком.";

return [{
  json: {
    chat_id: cb.message.chat.id,
    text,
    reply_markup: { inline_keyboard: rows }
  }
}];

const items = $input.all().filter(i => i.json && i.json.id);
const cb = $('Telegram Trigger').first().json.callback_query;
const page = parseInt(cb.data.split('_')[1]) || 0;
const hasNext = items.length > 5;
const list = hasNext ? items.slice(0, 5) : items;

if (list.length === 0 && page === 0) {
    return [{
        json: {
            chat_id: cb.message.chat.id,
            text: "У вас пока нет добавленных городов.",
            reply_markup: { inline_keyboard: [[{ text: "➕ Добавить город", callback_data: "add_city" }]] }
        }
    }];
}

const rows = [];
for (const item of list) {
    // Проверяем kind вместо type
    const isDistrict = item.json.kind === 'city_district' || item.json.kind === 'district';

    const btnText = (isDistrict && item.json.parent_name) 
        ? `${item.json.city_name} (${item.json.parent_name})` 
        : `${item.json.city_name}`;

    rows.push([{
        text: btnText,
        callback_data: `get_weather_${item.json.id}` 
    }]);
}

// Пагинация
const nav = [];
if (page > 0) nav.push({ text: "⬅️ Назад", callback_data: `weather_${page - 1}` });
if (hasNext) nav.push({ text: "Дальше ➡️", callback_data: `weather_${page + 1}` });
if (nav.length) rows.push(nav);
rows.push([{ text: "🏠 Главное меню", callback_data: "back_to_menu" }]);

return [{
    json: {
        chat_id: cb.message.chat.id,
        text: "🌤 *Выберите город, чтобы узнать погоду:*",
        reply_markup: { inline_keyboard: rows }
    }
}];

const loc = $('Get Location Data').first().json;
const chatId = $('Telegram Trigger').first().json.callback_query.message.chat.id;
// Legacy Markdown: экранировать внутри *жирного* нельзя, поэтому служебные символы просто убираем
const clean = s => String(s == null ? '' : s).replace(/[_*`\[\]]/g, ' ').trim();

const WMO = {
  0: ['☀️', 'Ясно'], 1: ['🌤', 'Преимущественно ясно'], 2: ['⛅', 'Переменная облачность'], 3: ['☁️', 'Пасмурно'],
  45: ['🌫', 'Туман'], 48: ['🌫', 'Изморозевый туман'],
  51: ['🌦', 'Лёгкая морось'], 53: ['🌦', 'Морось'], 55: ['🌧', 'Сильная морось'],
  56: ['🌧', 'Ледяная морось'], 57: ['🌧', 'Сильная ледяная морось'],
  61: ['🌦', 'Небольшой дождь'], 63: ['🌧', 'Дождь'], 65: ['🌧', 'Сильный дождь'],
  66: ['🌧', 'Ледяной дождь'], 67: ['🌧', 'Сильный ледяной дождь'],
  71: ['🌨', 'Небольшой снег'], 73: ['🌨', 'Снег'], 75: ['❄️', 'Сильный снег'], 77: ['🌨', 'Снежные зёрна'],
  80: ['🌦', 'Небольшой ливень'], 81: ['🌧', 'Ливень'], 82: ['⛈', 'Сильный ливень'],
  85: ['🌨', 'Небольшой снегопад'], 86: ['❄️', 'Сильный снегопад'],
  95: ['⛈', 'Гроза'], 96: ['⛈', 'Гроза с градом'], 99: ['⛈', 'Сильная гроза с градом']
};

const res = ($input.first() || {}).json || {};
const cw = res.current_weather;
let text;
if (!cw || cw.temperature === undefined) {
  text = `⚠️ Не удалось получить погоду для ${clean(loc.name)}. Попробуйте позже.`;
} else {
  const temp = Math.round(cw.temperature);
  const wind = Math.round(cw.windspeed);
  const [emoji, desc] = WMO[cw.weathercode] || ['🌡', `Код погоды ${cw.weathercode}`];

  // Склонение берём из базы (колонка name_prep: «в Саратове», «в Заводском районе»)
  const title = loc.name_prep ? `Погода ${clean(loc.name_prep)}` : `Погода: ${clean(loc.name)}`;
  let suffix = '';
  if (loc.parent_name && !loc.parent_is_region && ['city_district', 'locality', 'settlement', 'district'].includes(loc.kind)) {
    const pt = String(loc.parent_type || '').toLowerCase();
    suffix = ` (${clean(loc.parent_name)}${pt.startsWith('р-н') ? ' район' : ''})`;
  }

  let usedParent = false;
  try { usedParent = $('Use Parent Coords').isExecuted === true; } catch (e) { usedParent = false; }

  text = `🌤 *${title}${suffix}*\n\n${emoji} ${desc}, ${temp > 0 ? '+' : ''}${temp}°C\n💨 Ветер: ${wind} км/ч`;
  if (usedParent) text += `\n\n_ℹ️ Координаты района не найдены, показана погода по городу._`;
}
return [{ json: { chat_id: chatId, text } }];

const first = ($input.first() || {}).json || {};
const lat = parseFloat(first.lat);
const lon = parseFloat(first.lon);
if (!first.error && Number.isFinite(lat) && Number.isFinite(lon)) {
  return [{ json: { found: true, lat, lon, source: 'nominatim' } }];
}
return [{ json: { found: false } }];

const loc = $('Get Location Data').first().json;
const norm = s => String(s || '').toLowerCase().replace(/ё/g, 'е').trim();

const regionFull = (name, type) => {
  const t = norm(type);
  if (!name) return '';
  if (t.startsWith('аобл')) return `${name} автономная область`;
  if (t.startsWith('обл')) return `${name} область`;
  if (t.startsWith('край')) return `${name} край`;
  if (t.startsWith('респ')) return `Республика ${name}`;
  if (t === 'ао') return `${name} автономный округ`;
  return name;
};

const parts = [loc.name];
if (loc.parent_name && !loc.parent_is_region) {
  parts.push(norm(loc.parent_type).startsWith('р-н') ? `${loc.parent_name} район` : loc.parent_name);
}
const region = regionFull(loc.region_name, loc.region_type);
if (region) parts.push(region);

const seen = new Set();
const uniq = parts.filter(p => { const k = norm(p); if (!k || seen.has(k)) return false; seen.add(k); return true; });

return [{ json: {
  q: uniq.join(', '),
  name: loc.name,
  region_name: loc.region_name || '',
  parent_name: (!loc.parent_is_region && norm(loc.parent_type).startsWith('р-н')) ? loc.parent_name : ''
} }];

const ctx = $('Build Geocode Query').first().json;
const body = ($input.first() || {}).json || {};
const results = Array.isArray(body.results) ? body.results : [];
const norm = s => String(s || '').toLowerCase().replace(/ё/g, 'е').trim();
const stem = s => norm(s).slice(0, 5).trim();

// 1) то же название, 2) тот же регион (иначе можно получить одноимённое место за тысячу км)
let c = results.filter(r => norm(r.name) === norm(ctx.name));
if (ctx.region_name) c = c.filter(r => norm(r.admin1).includes(stem(ctx.region_name)));
// 3) если известен район, предпочитаем совпадение по нему
if (ctx.parent_name) {
  const byParent = c.filter(r => norm(r.admin2).includes(stem(ctx.parent_name)));
  if (byParent.length) c = byParent;
}
if (!c.length || !Number.isFinite(c[0].latitude) || !Number.isFinite(c[0].longitude)) {
  return [{ json: { found: false } }];
}
return [{ json: { found: true, lat: c[0].latitude, lon: c[0].longitude, source: 'open-meteo' } }];

// 1. Берем данные ИЗ ВХОДЯЩЕГО УЗЛА (SQL)
const items = $input.all().filter(i => i.json && i.json.id);
const cb = $('Telegram Trigger').first().json.callback_query;

// 2. Получаем страницу (my_cities_1 -> 1, my_cities -> 0)
const page = parseInt(cb.data.replace('my_cities_', '').replace('my_cities', '')) || 0;

// 3. Формируем список (максимум 5)
const hasNext = items.length > 5;
const list = hasNext ? items.slice(0, 5) : items;

if (list.length === 0 && page === 0) {
    return [{
        json: {
            chat_id: cb.message.chat.id,
            text: "У вас пока нет добавленных городов.",
            reply_markup: { inline_keyboard: [[{ text: "➕ Добавить город", callback_data: "add_city" }]] }
        }
    }];
}

const rows = [];

// 4. Кнопки удаления
for (const item of list) {
    const loc = item.json;
    const isDistrict = loc.kind === 'city_district' || loc.kind === 'district';
    const title = (isDistrict && loc.parent_name) ? `${loc.city_name} (${loc.parent_name})` : `${loc.city_name}`;

    rows.push([{ text: `❌ Удалить: ${title}`, callback_data: `del_${loc.id}` }]);
}

// 5. ПАГИНАЦИЯ
const nav = [];
// Если мы не на первой странице, добавляем кнопку "Назад"
if (page > 0) {
    nav.push({ text: "⬅️ Назад", callback_data: `my_cities_${page - 1}` });
}
// Если есть еще данные, добавляем "Дальше"
if (hasNext) {
    nav.push({ text: "Дальше ➡️", callback_data: `my_cities_${page + 1}` });
}
// Если есть хоть одна кнопка навигации, добавляем её в общий список
if (nav.length) {
    rows.push(nav);
}

// 6. Кнопка возврата в настройки
rows.push([{ text: "⬅️ Назад в настройки", callback_data: "settings" }]);

// 7. Невидимый символ
const hiddenChar = "\u200B";

return [{
    json: {
        chat_id: cb.message.chat.id,
        text: `🗑 *Выберите город, который нужно удалить:*\n${hiddenChar}`,
        reply_markup: { inline_keyboard: rows }
    }
}];

const TZ = [
  { id: 'Europe/Kaliningrad', label: 'Калининград (МСК-1)' },
  { id: 'Europe/Moscow', label: 'Москва (МСК)' },
  { id: 'Europe/Samara', label: 'Самара, Саратов (МСК+1)' },
  { id: 'Asia/Yekaterinburg', label: 'Екатеринбург (МСК+2)' },
  { id: 'Asia/Omsk', label: 'Омск (МСК+3)' },
  { id: 'Asia/Krasnoyarsk', label: 'Красноярск, Новосибирск (МСК+4)' },
  { id: 'Asia/Irkutsk', label: 'Иркутск (МСК+5)' },
  { id: 'Asia/Yakutsk', label: 'Якутск (МСК+6)' },
  { id: 'Asia/Vladivostok', label: 'Владивосток (МСК+7)' },
  { id: 'Asia/Magadan', label: 'Магадан (МСК+8)' },
  { id: 'Asia/Kamchatka', label: 'Камчатка (МСК+9)' }
];
const cb = $('Telegram Trigger').first().json.callback_query;
const d = String(cb.data || '');
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const out = { act: 'none', tg: String(cb.from.id), loc: '', t: '', nid: '', tz: '' };

if (d === 'ntoggle') {
  out.act = 'toggle';
} else if (d.startsWith('ntz_')) {
  const z = TZ[parseInt(d.slice(4), 10)];
  if (z) { out.act = 'tz'; out.tz = z.id; }
} else if (d.startsWith('nm_')) {            // nm_<uuid>_<HHMM>
  const p = d.split('_');
  const hm = p[2] || '';
  if (UUID.test(p[1] || '') && /^\d{4}$/.test(hm)) {
    const h = +hm.slice(0, 2), m = +hm.slice(2);
    if (h < 24 && m < 60 && m % 5 === 0) { out.act = 'add'; out.loc = p[1]; out.t = hm.slice(0, 2) + ':' + hm.slice(2); }
  }
} else if (d.startsWith('nd_') || d.startsWith('ne_')) {   // nd_<id>_<uuid> удалить, ne_<id>_<uuid> вкл/выкл
  const p = d.split('_');
  if (/^\d{1,9}$/.test(p[1] || '') && UUID.test(p[2] || '')) { out.act = d.startsWith('nd_') ? 'del' : 'flip'; out.nid = p[1]; out.loc = p[2]; }
}
return [{ json: out }];

const TZ = [
  { id: 'Europe/Kaliningrad', label: 'Калининград (МСК-1)' },
  { id: 'Europe/Moscow', label: 'Москва (МСК)' },
  { id: 'Europe/Samara', label: 'Самара, Саратов (МСК+1)' },
  { id: 'Asia/Yekaterinburg', label: 'Екатеринбург (МСК+2)' },
  { id: 'Asia/Omsk', label: 'Омск (МСК+3)' },
  { id: 'Asia/Krasnoyarsk', label: 'Красноярск, Новосибирск (МСК+4)' },
  { id: 'Asia/Irkutsk', label: 'Иркутск (МСК+5)' },
  { id: 'Asia/Yakutsk', label: 'Якутск (МСК+6)' },
  { id: 'Asia/Vladivostok', label: 'Владивосток (МСК+7)' },
  { id: 'Asia/Magadan', label: 'Магадан (МСК+8)' },
  { id: 'Asia/Kamchatka', label: 'Камчатка (МСК+9)' }
];
const cb = $('Telegram Trigger').first().json.callback_query;
const d = String(cb.data || '');
const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const clean = s => String(s == null ? '' : s).replace(/[_*`\[\]]/g, ' ').trim();
const MAX = 5, PAGE = 5;

const timesOf = r => Array.isArray(r.times) ? r.times : JSON.parse(r.times || '[]');
const allTimes = rows.flatMap(timesOf);
const notifyOn = allTimes.some(t => t.on);   // включено, если включено хотя бы одно время в любом городе
const tzId = rows.length ? rows[0].tz : 'Europe/Moscow';
const tzLabel = (TZ.find(z => z.id === tzId) || { label: tzId }).label;
const titleOf = r => (['city_district', 'district'].includes(r.kind) && r.parent_name) ? `${r.city_name} (${r.parent_name})` : r.city_name;
const cut = (s, n) => s.length > n ? s.slice(0, n - 1) + '…' : s;

let mode = 'list', page = 0, locId = '', hh = '';
if (d.startsWith('notify_')) page = parseInt(d.slice(7), 10) || 0;
else if (d === 'ntz') mode = 'tz';
else if (d.startsWith('nt_')) { mode = 'city'; locId = d.slice(3); }
else if (d.startsWith('na_')) { mode = 'hour'; locId = d.slice(3); }
else if (d.startsWith('nh_')) { const p = d.split('_'); mode = 'min'; locId = p[1]; hh = p[2] || ''; }
else if (d.startsWith('nm_')) { mode = 'city'; locId = d.split('_')[1]; }
else if (d.startsWith('nd_') || d.startsWith('ne_')) { mode = 'city'; locId = d.split('_')[2]; }

const city = rows.find(r => r.id === locId);
if (['city', 'hour', 'min'].includes(mode) && !city) mode = 'list';
if (mode === 'min' && !/^\d{2}$/.test(hh)) mode = 'hour';

let text, kb = [];

if (mode === 'tz') {
  text = '🕒 Часовой пояс\nВремя уведомлений считается по выбранному поясу:';
  let row = [];
  TZ.forEach((z, i) => {
    row.push({ text: (z.id === tzId ? '✅ ' : '') + z.label, callback_data: `ntz_${i}` });
    if (row.length === 2) { kb.push(row); row = []; }
  });
  if (row.length) kb.push(row);
  kb.push([{ text: '⬅️ Назад', callback_data: 'notify' }]);

} else if (mode === 'city') {
  const times = timesOf(city);
  text = `📍 ${clean(titleOf(city))}\n\n` +
    (times.length ? `Времена (${times.length} из ${MAX}), 🟢 вкл / 🔴 выкл:\n` + times.map(t => `${t.on ? '🟢' : '🔴'} ${t.t}`).join('\n') : 'Уведомлений пока нет.') +
    `\n\n🕒 Часовой пояс: ${clean(tzLabel)}` +
    (times.length >= MAX ? '\n\nДостигнут лимит времён для этого города.' : '');
  let row = [];
  for (const t of times) {
    kb.push([{ text: `${t.on ? '🟢 Вкл' : '🔴 Выкл'} · ${t.t}`, callback_data: `ne_${t.id}_${locId}` },
             { text: '🗑 Удалить', callback_data: `nd_${t.id}_${locId}` }]);
  }
  if (times.length < MAX) kb.push([{ text: '➕ Добавить время', callback_data: `na_${locId}` }]);
  kb.push([{ text: '⬅️ К списку', callback_data: 'notify' }]);

} else if (mode === 'hour') {
  text = `🕐 ${clean(titleOf(city))}\nВыберите час (${clean(tzLabel)}):`;
  let row = [];
  for (let h = 0; h < 24; h++) {
    const H = String(h).padStart(2, '0');
    row.push({ text: `${H}:00`, callback_data: `nh_${locId}_${H}` });
    if (row.length === 4) { kb.push(row); row = []; }
  }
  kb.push([{ text: '⬅️ Назад', callback_data: `nt_${locId}` }]);

} else if (mode === 'min') {
  text = `🕐 ${clean(titleOf(city))}\nВыберите время (${clean(tzLabel)}):`;
  let row = [];
  for (let m = 0; m < 60; m += 5) {
    const M = String(m).padStart(2, '0');
    row.push({ text: `${hh}:${M}`, callback_data: `nm_${locId}_${hh}${M}` });
    if (row.length === 4) { kb.push(row); row = []; }
  }
  kb.push([{ text: '⬅️ Другой час', callback_data: `na_${locId}` }]);

} else if (rows.length === 0) {
  text = '🔔 Уведомления\n\nСначала добавьте хотя бы один город.';
  kb = [[{ text: '➕ Добавить город', callback_data: 'add_city' }], [{ text: '⬅️ Назад', callback_data: 'settings' }]];

} else {
  if (page * PAGE >= rows.length) page = 0;
  const list = rows.slice(page * PAGE, page * PAGE + PAGE);
  text = `🔔 Уведомления\n\nСтатус: ${notifyOn ? '🟢 включены' : '🔴 выключены'}\n🕒 Часовой пояс: ${clean(tzLabel)}\n\nВыберите город, чтобы настроить время:`;
  if (allTimes.length) kb.push([{ text: notifyOn ? '🔴 Выключить все' : '🟢 Включить все', callback_data: 'ntoggle' }]);
  kb.push([{ text: `🕒 Пояс: ${tzLabel}`, callback_data: 'ntz' }]);
  for (const r of list) {
    const ts = timesOf(r).map(t => (t.on ? '🟢' : '🔴') + t.t).join(' ');
    kb.push([{ text: cut(`📍 ${titleOf(r)} · ${ts || 'не настроено'}`, 60), callback_data: `nt_${r.id}` }]);
  }
  const nav = [];
  if (page > 0) nav.push({ text: '⬅️ Назад', callback_data: `notify_${page - 1}` });
  if ((page + 1) * PAGE < rows.length) nav.push({ text: 'Дальше ➡️', callback_data: `notify_${page + 1}` });
  if (nav.length) kb.push(nav);
  kb.push([{ text: '⚙️ Назад в настройки', callback_data: 'settings' }]);
}

return [{ json: { chat_id: cb.message.chat.id, text, reply_markup: { inline_keyboard: kb } } }];
